<?php use App\Core\Csrf;use App\Core\View;?><div class="page-header"><div><h1>신청 질문 관리</h1><p class="muted">정렬 번호가 낮은 질문부터 표시됩니다. 삭제 대신 비활성화합니다.</p></div><a class="button secondary" href="/admin/events">신청자 목록</a></div><?php if($success):?><div class="alert alert-success"><?=View::e($success)?></div><?php endif?><?php if($error):?><div class="alert alert-error"><?=View::e($error)?></div><?php endif?>
<section class="panel"><h2>질문 추가</h2><form method="post" action="/admin/events/<?=$invitationId?>/questions" class="form-grid"><input type="hidden" name="_token" value="<?=View::e(Csrf::token())?>"><label>질문<input name="label" maxlength="190" required></label><label>유형<select name="question_type"><option value="text">한 줄</option><option value="textarea">긴 글</option><option value="select">선택</option><option value="checkbox">체크</option></select></label><label>정렬<input type="number" name="sort_order" min="0" max="1000" value="0"></label><label><input type="checkbox" name="is_required"> 필수 답변</label><label class="full">선택 항목 (한 줄에 하나)<textarea name="options"></textarea></label><button class="primary">추가</button></form></section>
<section class="panel"><h2>등록 질문</h2><?php foreach($questions as $q):?><form method="post" action="/admin/events/<?=$invitationId?>/questions" class="form-grid"><input type="hidden" name="_token" value="<?=View::e(Csrf::token())?>"><input type="hidden" name="id" value="<?=$q['id']?>"><label>질문<input name="label" maxlength="190" value="<?=View::e($q['label'])?>"></label><label>유형<select name="question_type"><?php foreach(['text','textarea','select','checkbox'] as $v):?><option <?=$q['question_type']===$v?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label>정렬<input type="number" name="sort_order" value="<?=$q['sort_order']?>"></label><label><input type="checkbox" name="is_required" <?=$q['is_required']?'checked':''?>> 필수</label><label class="full">선택 항목<textarea name="options"><?=View::e(implode("\n",json_decode((string)($q['options_json']??'[]'),true)?:[]))?></textarea></label><button class="secondary">수정</button></form><?php if($q['is_active']):?><form method="post" action="/admin/events/<?=$invitationId?>/questions/<?=$q['id']?>/deactivate"><input type="hidden" name="_token" value="<?=View::e(Csrf::token())?>"><button class="danger">비활성화</button></form><?php endif?><hr><?php endforeach?></section>
